  const router = useRouter();

  const [step, setStep] = useState<Step>('Register');
  const [isLoading, setIsLoading] = useState(false);
  const [userId, setUserId] = useState('');

  // Form state
  const [formData, setFormData] = useState({
    email: '',
    password: '',
    confirmPassword: '',
    firstName: '',
    lastName: '',
    dateOfBirth: '',
    gender: '',
    phone: '',
