    29|const CODE_TTL_MINUTES = 10;
    30|const CODE_LENGTH = 6;
    31|const MAX_ATTEMPTS = 5;
    32|
    33|function getSupabaseAdmin(): SupabaseClient {
    34|  const url = process.env.SUPABASE_URL || process.env.EXPO_PUBLIC_SUPABASE_URL || '';
    35|  // Service-role key first; anon key as a working fallback (service key was rotated).
    36|  const key =
    37|    process.env.SUPABASE_SERVICE_ROLE_KEY ||
    38|    process.env.SUPABASE_SERVICE_KEY ||
    39|    process.env.SUPABASE_ANON_KEY ||
    40|    process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY ||
    41|    '';
    42|  return createClient(url, key, {
    43|    auth: { persistSession: false, autoRefreshToken: false },
    44|  });
    45|}
    46|
    47|function generateCode(): string {
    48|  let code = '';
    49|  for (let i = 0; i < CODE_LENGTH; i++) {
    50|    code += Math.floor(Math.random() * 10).toString();
    51|  }
    52|  return code;
    53|}
    54|
    55|// ---------------------------------------------------------------------------
    56|// Fallback store (used when the Supabase schema is missing/unavailable)
    57|// ---------------------------------------------------------------------------
    58|
    59|interface FallbackCodeRecord {
    60|  userId: string;
    61|  type: 'email' | 'phone';
    62|  code: string;
    63|  attempts: number;
    64|  expiresAt: string;
    65|  verifiedAt: string | null;
    66|  createdAt: string;
    67|}
    68|
    69|type FallbackCodesStore = Record<string, FallbackCodeRecord>;
    70|type FallbackStatusStore = Record<string, { emailVerified: boolean; phoneVerified: boolean; updatedAt: string }>;
    71|
    72|const STORE_DIR = (): string => path.join(process.cwd(), 'logs', 'audit', 'member-verification');
    73|const CODES_FILE = (): string => path.join(STORE_DIR(), 'verification-codes.json');
    74|const STATUS_FILE = (): string => path.join(STORE_DIR(), 'verification-status.json');
    75|
    76|function codeKey(userId: string, type: 'email' | 'phone'): string {
    77|  return `${userId}:${type}`;
    78|}
    79|
    80|async function readStore<T>(file: string, fallback: T): Promise<T> {
    81|  if (isDurableStoreConfigured()) {
    82|    try {
    83|      return await readDurableJson<T>(file, fallback);
    84|    } catch {
    85|      return fallback;
    86|    }
    87|  }
    88|  try {
    89|    const raw = await readFile(file, 'utf8');
    90|    return JSON.parse(raw) as T;
    91|  } catch {
    92|    return fallback;
    93|  }
    94|}
    95|
    96|async function writeStore<T>(file: string, value: T): Promise<void> {
    97|  if (isDurableStoreConfigured()) {
    98|    try {
    99|      await writeDurableJson(file, value);
   100|      return;
   101|    } catch {
   102|      // fall through to filesystem
   103|    }
   104|  }
   105|  await mkdir(path.dirname(file), { recursive: true });
   106|  await writeFile(file, JSON.stringify(value, null, 2), 'utf8');
   107|}
   108|
   109|async function fallbackStoreCode(input: StoreCodeInput, code: string, expiresAt: Date): Promise<void> {
   110|  const codes = await readStore<FallbackCodesStore>(CODES_FILE(), {});
   111|  codes[codeKey(input.userId, input.type)] = {
   112|    userId: input.userId,
